import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.D2veAa-g.js";const p=JSON.parse('{"title":"计算机硬件","description":"","frontmatter":{"title":"计算机硬件"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/计算机系统基础知识/计算机硬件.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/计算机系统基础知识/计算机硬件.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/计算机系统基础知识/计算机硬件.md"};function r(n,l,c,g,e,u){return s(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="计算机硬件" tabindex="-1">计算机硬件 <a class="header-anchor" href="#计算机硬件" aria-label="Permalink to &quot;计算机硬件&quot;">​</a></h1><blockquote><p>共 47 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-risc-精简指令系统计算机-的特点不包括" tabindex="-1">Q1. RISC(精简指令系统计算机）的特点不包括：（） <a class="header-anchor" href="#q1-risc-精简指令系统计算机-的特点不包括" aria-label="Permalink to &quot;Q1. RISC(精简指令系统计算机）的特点不包括：（）&quot;">​</a></h2><ul><li><strong>A.</strong> 指令长度固定，指令种类尽量少</li><li><strong>B.</strong> 寻址方式尽量丰富，指令功能尽可能强</li><li><strong>C.</strong> 增加寄存器数目，以减少访存次数</li><li><strong>D.</strong> 用硬布线电路实现指令解码，以尽快完成指令译码</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q2-某计算机系统输入-输出采用双缓冲工作方式-其工作过程如下图所示" tabindex="-1">Q2. 某计算机系统输入/输出采用双缓冲工作方式，其工作过程如下图所示， <a class="header-anchor" href="#q2-某计算机系统输入-输出采用双缓冲工作方式-其工作过程如下图所示" aria-label="Permalink to &quot;Q2. 某计算机系统输入/输出采用双缓冲工作方式，其工作过程如下图所示，&quot;">​</a></h2><p>假设磁盘块与缓冲区大小相同，每个盘块读入缓冲区的时间T为10μs，缓冲区送用户区的时间M为6μs，系统对每个磁盘块数据的处理时间C为2μs。若用户需要将大小为10个磁盘块的Docl文件逐块从磁盘读入缓冲区，并送用户区进行处理，那么采用双缓冲需要花费的时间<strong>为（请作答此空）μs</strong>，</p><p>比使用单缓冲节约了（ ）μs时间。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260512165112.png" alt="image.png"></p><ul><li><strong>A.</strong> 100</li><li><strong>B.</strong> 108</li><li><strong>C.</strong> 162</li><li><strong>D.</strong> 180</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260512173550.png" alt=""></p></div></details><h2 id="q3-目前处理器市场中存在cpu和dsp两种类型处理器-分别用于不同场景-这两种处理器具有不同的体系结构-dsp采用-。" tabindex="-1">Q3. 目前处理器市场中存在CPU和DSP两种类型处理器，分别用于不同场景，这两种处理器具有不同的体系结构，DSP采用（ ）。 <a class="header-anchor" href="#q3-目前处理器市场中存在cpu和dsp两种类型处理器-分别用于不同场景-这两种处理器具有不同的体系结构-dsp采用-。" aria-label="Permalink to &quot;Q3. 目前处理器市场中存在CPU和DSP两种类型处理器，分别用于不同场景，这两种处理器具有不同的体系结构，DSP采用（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 冯.诺伊曼结构</li><li><strong>B.</strong> 哈佛结构</li><li><strong>C.</strong> FPGA结构</li><li><strong>D.</strong> 与GPU相同结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><h3 id="解析" tabindex="-1">解析 <a class="header-anchor" href="#解析" aria-label="Permalink to &quot;解析&quot;">​</a></h3><p><strong>DSP（数字信号处理器）</strong> 的典型体系结构是<strong>哈佛结构</strong>或<strong>改进的哈佛结构</strong>。</p><p>常见DSP（如TI TMS320系列）都采用<strong>哈佛结构</strong>或其变种，以实现指令流水线的高效率。</p><table tabindex="0"><thead><tr><th style="text-align:left;">选项</th><th style="text-align:left;">结构特点</th><th style="text-align:left;">是否DSP采用</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A. 冯·诺依曼结构</strong></td><td style="text-align:left;">指令和数据共用同一总线，顺序执行</td><td style="text-align:left;">❌ 传统CPU采用，DSP不用</td></tr><tr><td style="text-align:left;"><strong>B. 哈佛结构</strong></td><td style="text-align:left;">指令存储器和数据存储器<strong>分开</strong>，有独立总线，可<strong>并行读取</strong>指令和数据</td><td style="text-align:left;">✅ <strong>正确</strong>。DSP需要高速数据处理，哈佛结构支持指令预取和数据同时访问，提高吞吐量</td></tr><tr><td style="text-align:left;"><strong>C. FPGA结构</strong></td><td style="text-align:left;">现场可编程门阵列，是一种硬件可重构器件，不是处理器体系结构分类</td><td style="text-align:left;">❌ 不属于CPU/DSP的体系结构类型</td></tr><tr><td style="text-align:left;"><strong>D. 与GPU相同结构</strong></td><td style="text-align:left;">GPU采用流式多处理器+大量计算单元，与DSP不同</td><td style="text-align:left;">❌ DSP和GPU体系结构不同，DSP更侧重低功耗、确定性实时处理</td></tr></tbody></table></div></details><h2 id="q4-以下关于串行总线的说法中-正确的是-。" tabindex="-1">Q4. 以下关于串行总线的说法中，正确的是（ ）。 <a class="header-anchor" href="#q4-以下关于串行总线的说法中-正确的是-。" aria-label="Permalink to &quot;Q4. 以下关于串行总线的说法中，正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 串行总线一般都是全双工总线，适宜于长距离传输数据</li><li><strong>B.</strong> 串行总线传输的波特率是总线初始化时预先定义好的，使用中不可改变</li><li><strong>C.</strong> 串行总线是按位（bit）传输数据的，其数据的正确性依赖于校验码纠正</li><li><strong>D.</strong> 串行总线的数据发送和接收是以软件查询方式工作</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q5-假如有-4-块-80t-的硬盘-采用-raid6-组建磁盘阵列的容量是-。" tabindex="-1">Q5. 假如有 4 块 80T 的硬盘，采用 RAID6 组建磁盘阵列的容量是（ ）。 <a class="header-anchor" href="#q5-假如有-4-块-80t-的硬盘-采用-raid6-组建磁盘阵列的容量是-。" aria-label="Permalink to &quot;Q5. 假如有 4 块 80T 的硬盘，采用 RAID6 组建磁盘阵列的容量是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 40T</li><li><strong>B.</strong> 80T</li><li><strong>C.</strong> 160T</li><li><strong>D.</strong> 240T</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q6-执行指令时-将每一节指令都分解为取指、分析和执行三步" tabindex="-1">Q6. 执行指令时，将每一节指令都分解为取指、分析和执行三步， <a class="header-anchor" href="#q6-执行指令时-将每一节指令都分解为取指、分析和执行三步" aria-label="Permalink to &quot;Q6. 执行指令时，将每一节指令都分解为取指、分析和执行三步，&quot;">​</a></h2><p>已知取指时间t取指=5△t，分析时间t分析= 2△t.执行时间t执行= 3△t如果按照重叠的流水线方式执行指令，从头到尾执行完500条指令需（ ）△t.</p><ul><li><strong>A.</strong> 2500</li><li><strong>B.</strong> 2505</li><li><strong>C.</strong> 2510</li><li><strong>D.</strong> 2515</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q7-计算机系统中-方式是根据所访问的内容来决定要访问的存储单元-常用在-存储器中。" tabindex="-1">Q7. 计算机系统中，（）方式是根据所访问的内容来决定要访问的存储单元，常用在（）存储器中。 <a class="header-anchor" href="#q7-计算机系统中-方式是根据所访问的内容来决定要访问的存储单元-常用在-存储器中。" aria-label="Permalink to &quot;Q7. 计算机系统中，（）方式是根据所访问的内容来决定要访问的存储单元，常用在（）存储器中。&quot;">​</a></h2><ul><li><strong>A.</strong> 顺序存取</li><li><strong>B.</strong> 直接存取</li><li><strong>C.</strong> 随机存取</li><li><strong>D.</strong> 相联存取</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q8-计算机系统中-方式是根据所访问的内容来决定要访问的存储单元-常用在-存储器中。" tabindex="-1">Q8. 计算机系统中，（）方式是根据所访问的内容来决定要访问的存储单元，常用在（）存储器中。 <a class="header-anchor" href="#q8-计算机系统中-方式是根据所访问的内容来决定要访问的存储单元-常用在-存储器中。" aria-label="Permalink to &quot;Q8. 计算机系统中，（）方式是根据所访问的内容来决定要访问的存储单元，常用在（）存储器中。&quot;">​</a></h2><ul><li><strong>A.</strong> DRAM</li><li><strong>B.</strong> Cache</li><li><strong>C.</strong> EEPROM</li><li><strong>D.</strong> CD-ROM</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q9-嵌入式系统中采用中断方式实现输入输出的主要原因是-1-。在中断时-cpu断点信息一般保存到-2-中。" tabindex="-1">Q9. 嵌入式系统中采用中断方式实现输入输出的主要原因是 （1） 。在中断时，CPU断点信息一般保存到 （2） 中。 <a class="header-anchor" href="#q9-嵌入式系统中采用中断方式实现输入输出的主要原因是-1-。在中断时-cpu断点信息一般保存到-2-中。" aria-label="Permalink to &quot;Q9. 嵌入式系统中采用中断方式实现输入输出的主要原因是 （1） 。在中断时，CPU断点信息一般保存到 （2） 中。&quot;">​</a></h2><ul><li><strong>A.</strong> 速度最快</li><li><strong>B.</strong> CPU不参与操作</li><li><strong>C.</strong> 实现起来比较容易</li><li><strong>D.</strong> 能对突发事件做出快速响应</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q10-嵌入式系统中采用中断方式实现输入输出的主要原因是-1-。在中断时-cpu断点信息一般保存到-2-中。" tabindex="-1">Q10. 嵌入式系统中采用中断方式实现输入输出的主要原因是 （1） 。在中断时，CPU断点信息一般保存到 （2） 中。 <a class="header-anchor" href="#q10-嵌入式系统中采用中断方式实现输入输出的主要原因是-1-。在中断时-cpu断点信息一般保存到-2-中。" aria-label="Permalink to &quot;Q10. 嵌入式系统中采用中断方式实现输入输出的主要原因是 （1） 。在中断时，CPU断点信息一般保存到 （2） 中。&quot;">​</a></h2><ul><li><strong>A.</strong> 通用寄存器</li><li><strong>B.</strong> 堆</li><li><strong>C.</strong> 栈</li><li><strong>D.</strong> I/O接口</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>根据嵌入式系统的基本原理，正确答案为：</p><ul><li><strong>(1) D. 能对突发事件做出快速响应</strong><br> 中断方式的主要优点是使CPU能够及时处理外部突发事件，提高系统的实时性。</li><li><strong>(2) 堆栈（栈）</strong><br> 中断发生时，CPU会把当前的断点信息（如程序计数器PC、状态寄存器等）自动压入堆栈保存，以便中断返回后能继续执行原程序。<br> 注：第二问的题目中未列出选项，但常见软考题中该空的标准答案是“堆栈”。如果选项中有“堆栈”，则选它；若有“内存”，则不精确，推荐选“堆栈”。</li></ul></div></details><h2 id="q11-【51cto学堂-学员回忆版】ai芯片是当前人工智能技术发展的核心技术-其能力要支持训练和推理。通常-ai芯片的技术架构包括-11-等三种。" tabindex="-1">Q11. 【51CTO学堂-学员回忆版】AI芯片是当前人工智能技术发展的核心技术，其能力要支持训练和推理。通常，AI芯片的技术架构包括(11)等三种。 <a class="header-anchor" href="#q11-【51cto学堂-学员回忆版】ai芯片是当前人工智能技术发展的核心技术-其能力要支持训练和推理。通常-ai芯片的技术架构包括-11-等三种。" aria-label="Permalink to &quot;Q11. 【51CTO学堂-学员回忆版】AI芯片是当前人工智能技术发展的核心技术，其能力要支持训练和推理。通常，AI芯片的技术架构包括(11)等三种。&quot;">​</a></h2><ul><li><strong>A.</strong> GPU、FPGA、ASIC</li><li><strong>B.</strong> CPU、PPGA、DSP</li><li><strong>C.</strong> GPU、CPU、ASIC</li><li><strong>D.</strong> GPU、FPGA、SOC</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q12-【51cto学堂-学员回忆版】通常-嵌入式中间件没有统一的架构风格-根据应用对象的不同可存在多种类型-比较常见的是消息中间件和分布式对象中间件。以下有关消息中间件的描述中-不正确的是-12-。" tabindex="-1">Q12. 【51CTO学堂-学员回忆版】通常，嵌入式中间件没有统一的架构风格，根据应用对象的不同可存在多种类型，比较常见的是消息中间件和分布式对象中间件。以下有关消息中间件的描述中，不正确的是(12)。 <a class="header-anchor" href="#q12-【51cto学堂-学员回忆版】通常-嵌入式中间件没有统一的架构风格-根据应用对象的不同可存在多种类型-比较常见的是消息中间件和分布式对象中间件。以下有关消息中间件的描述中-不正确的是-12-。" aria-label="Permalink to &quot;Q12. 【51CTO学堂-学员回忆版】通常，嵌入式中间件没有统一的架构风格，根据应用对象的不同可存在多种类型，比较常见的是消息中间件和分布式对象中间件。以下有关消息中间件的描述中，不正确的是(12)。&quot;">​</a></h2><ul><li><strong>A.</strong> 消息中间件是消息传输过程中保存消息的一种容器</li><li><strong>B.</strong> 消息中间件具有两个基本特点：来用异步处理模式、应用程序和应用程序调用关系为松耦合关系</li><li><strong>C.</strong> 消息中间件主要由一组对象来提供系统服务，对象间能够跨平台通信</li><li><strong>D.</strong> 消息中间件的消息传递服务模型有点对点模型和发布-订阅模型之分</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>解析</p><ul><li><strong>A</strong>：正确。消息中间件通常作为消息的暂存容器，支持存储转发。</li><li><strong>B</strong>：正确。消息中间件采用异步通信，且发送方和接收方松耦合。</li><li><strong>C</strong>：不正确。该描述更符合<strong>分布式对象中间件</strong>（如 CORBA、RMI、EJB）的特征——由一组对象提供跨平台服务。消息中间件的核心是<strong>消息队列和通道</strong>，而非“一组对象”。</li><li><strong>D</strong>：正确。点对点（队列）和发布-订阅（主题）是消息中间件的两种经典模型。</li></ul><p>所以，本题应选 <strong>C</strong>。</p></div></details><h2 id="q13-内存按字节编址-地址从b0000h到dffffh的内存-共有-1-字节-若用存储容量为64k-4bit的存储器芯片构成该内存空间-至少需要-2-片。" tabindex="-1">Q13. 内存按字节编址，地址从B0000H到DFFFFH的内存，共有（1）字节，若用存储容量为64k* 4bit的存储器芯片构成该内存空间，至少需要（2）片。 <a class="header-anchor" href="#q13-内存按字节编址-地址从b0000h到dffffh的内存-共有-1-字节-若用存储容量为64k-4bit的存储器芯片构成该内存空间-至少需要-2-片。" aria-label="Permalink to &quot;Q13. 内存按字节编址，地址从B0000H到DFFFFH的内存，共有（1）字节，若用存储容量为64k* 4bit的存储器芯片构成该内存空间，至少需要（2）片。&quot;">​</a></h2><ul><li><strong>A.</strong> 4</li><li><strong>B.</strong> 5</li><li><strong>C.</strong> 6</li><li><strong>D.</strong> 8</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>解析</p><ol><li><p><strong>内存容量计算</strong><br> 地址范围：B0000H ～ DFFFFH<br> 总字节数 = DFFFFH - B0000H + 1 = 2FFFFH + 1 = 30000H<br> 转换为十进制：30000H = 3 × 16⁴ = 3 × 65536 = 196608 字节<br> 即 <strong>196608 B = 192 KB</strong>（因为 192 × 1024 = 196608）。</p></li><li><p><strong>芯片容量计算</strong><br> 芯片规格：64K × 4bit<br> 一片芯片的字节数 = (64 × 1024 × 4) / 8 = 64 × 1024 × 0.5 = 32 × 1024 = <strong>32 KB</strong>。</p></li><li><p><strong>所需片数</strong><br> 192 KB ÷ 32 KB = <strong>6 片</strong>。</p></li></ol><p>因此，至少需要 6 片该存储器芯片。</p></div></details><h2 id="q14-现代cpu中集成的核心部件是-。" tabindex="-1">Q14. 现代CPU中集成的核心部件是 （ ） 。 <a class="header-anchor" href="#q14-现代cpu中集成的核心部件是-。" aria-label="Permalink to &quot;Q14. 现代CPU中集成的核心部件是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 运算器和控制器</li><li><strong>B.</strong> 存储器和输入设备</li><li><strong>C.</strong> 总线和缓存</li><li><strong>D.</strong> GPU和DSP</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q15-以下指令集中开源无需授权的是-。" tabindex="-1">Q15. 以下指令集中开源无需授权的是 （ ） 。 <a class="header-anchor" href="#q15-以下指令集中开源无需授权的是-。" aria-label="Permalink to &quot;Q15. 以下指令集中开源无需授权的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> x86</li><li><strong>B.</strong> ARM</li><li><strong>C.</strong> RISC-V</li><li><strong>D.</strong> PowerPC</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q16-以下接口中属于网络接口的是-。" tabindex="-1">Q16. 以下接口中属于网络接口的是 （ ） 。 <a class="header-anchor" href="#q16-以下接口中属于网络接口的是-。" aria-label="Permalink to &quot;Q16. 以下接口中属于网络接口的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> HDMI</li><li><strong>B.</strong> SATA</li><li><strong>C.</strong> RJ45</li><li><strong>D.</strong> RS-232</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>解析</p><ul><li><strong>A. HDMI</strong>：高清多媒体接口，用于视频和音频传输，非网络接口。</li><li><strong>B. SATA</strong>：硬盘接口，用于连接存储设备。</li><li><strong>C. RJ45</strong>：标准以太网接口，用于有线网络连接。</li><li><strong>D. RS-232</strong>：串行通信接口，常用于老式设备或控制台，但不是网络接口（通常不用于 TCP/IP 网络）。</li></ul></div></details><h2 id="q17-cpu中的-1-负责执行算术和逻辑运算。以下-2-技术用于提高cpu的并行计算能力。" tabindex="-1">Q17. CPU中的 （1） 负责执行算术和逻辑运算。以下 （2） 技术用于提高CPU的并行计算能力。 <a class="header-anchor" href="#q17-cpu中的-1-负责执行算术和逻辑运算。以下-2-技术用于提高cpu的并行计算能力。" aria-label="Permalink to &quot;Q17. CPU中的 （1） 负责执行算术和逻辑运算。以下 （2） 技术用于提高CPU的并行计算能力。&quot;">​</a></h2><ul><li><strong>A.</strong> CU</li><li><strong>B.</strong> ALU</li><li><strong>C.</strong> 寄存器</li><li><strong>D.</strong> Cache</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q18-cpu中的-1-负责执行算术和逻辑运算。以下-2-技术用于提高cpu的并行计算能力。" tabindex="-1">Q18. CPU中的 （1） 负责执行算术和逻辑运算。以下 （2） 技术用于提高CPU的并行计算能力。 <a class="header-anchor" href="#q18-cpu中的-1-负责执行算术和逻辑运算。以下-2-技术用于提高cpu的并行计算能力。" aria-label="Permalink to &quot;Q18. CPU中的 （1） 负责执行算术和逻辑运算。以下 （2） 技术用于提高CPU的并行计算能力。&quot;">​</a></h2><ul><li><strong>A.</strong> 超线程技术</li><li><strong>B.</strong> 加密技术</li><li><strong>C.</strong> 缓存技术</li><li><strong>D.</strong> 压缩技术</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q19-下列-存储器的访问速度最快。" tabindex="-1">Q19. 下列 （ ） 存储器的访问速度最快。 <a class="header-anchor" href="#q19-下列-存储器的访问速度最快。" aria-label="Permalink to &quot;Q19. 下列 （ ） 存储器的访问速度最快。&quot;">​</a></h2><ul><li><strong>A.</strong> 主存（DRAM）</li><li><strong>B.</strong> 片上缓存（L1 Cache）</li><li><strong>C.</strong> 外存（如SSD）</li><li><strong>D.</strong> 片外缓存（L2 Cache）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q20-内存按字节编址-地址从b0000h到dffffh的内存-若用存储容量为64k-4bit的存储器芯片构成该内存空间-至少需要-片。" tabindex="-1">Q20. 内存按字节编址，地址从B0000H到DFFFFH的内存，若用存储容量为64k* 4bit的存储器芯片构成该内存空间，至少需要 （ ） 片。 <a class="header-anchor" href="#q20-内存按字节编址-地址从b0000h到dffffh的内存-若用存储容量为64k-4bit的存储器芯片构成该内存空间-至少需要-片。" aria-label="Permalink to &quot;Q20. 内存按字节编址，地址从B0000H到DFFFFH的内存，若用存储容量为64k* 4bit的存储器芯片构成该内存空间，至少需要 （ ） 片。&quot;">​</a></h2><ul><li><strong>A.</strong> 4</li><li><strong>B.</strong> 5</li><li><strong>C.</strong> 6</li><li><strong>D.</strong> 8</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q21-以下-一般采用哈佛体系结构。" tabindex="-1">Q21. 以下 （ ） 一般采用哈佛体系结构。 <a class="header-anchor" href="#q21-以下-一般采用哈佛体系结构。" aria-label="Permalink to &quot;Q21. 以下 （ ） 一般采用哈佛体系结构。&quot;">​</a></h2><ul><li><strong>A.</strong> GPU</li><li><strong>B.</strong> DSP</li><li><strong>C.</strong> FPGA</li><li><strong>D.</strong> ARM CPU</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q22-以下属于通用处理器的是" tabindex="-1">Q22. 以下属于通用处理器的是（） <a class="header-anchor" href="#q22-以下属于通用处理器的是" aria-label="Permalink to &quot;Q22. 以下属于通用处理器的是（）&quot;">​</a></h2><ul><li><strong>A.</strong> GPU</li><li><strong>B.</strong> DSP</li><li><strong>C.</strong> FPGA</li><li><strong>D.</strong> ARM CPU</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q23-以下存储层次中容量最大的是-。" tabindex="-1">Q23. 以下存储层次中容量最大的是 （ ） 。 <a class="header-anchor" href="#q23-以下存储层次中容量最大的是-。" aria-label="Permalink to &quot;Q23. 以下存储层次中容量最大的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 片上缓存</li><li><strong>B.</strong> 片外缓存</li><li><strong>C.</strong> 主存</li><li><strong>D.</strong> 外存</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q24-以下存储介质中属于非易失性存储的是-。" tabindex="-1">Q24. 以下存储介质中属于非易失性存储的是 （ ） 。 <a class="header-anchor" href="#q24-以下存储介质中属于非易失性存储的是-。" aria-label="Permalink to &quot;Q24. 以下存储介质中属于非易失性存储的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> SRAM</li><li><strong>B.</strong> DRAM</li><li><strong>C.</strong> Flash</li><li><strong>D.</strong> 寄存器</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q25-以下设备中需要通过a-d转换接口连接的是-。" tabindex="-1">Q25. 以下设备中需要通过A/D转换接口连接的是 （ ） 。 <a class="header-anchor" href="#q25-以下设备中需要通过a-d转换接口连接的是-。" aria-label="Permalink to &quot;Q25. 以下设备中需要通过A/D转换接口连接的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 键盘</li><li><strong>B.</strong> 麦克风</li><li><strong>C.</strong> 显示器</li><li><strong>D.</strong> 打印机</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q26-在raid技术中-哪种raid级别提供了最高的i-o性能和磁盘空间利用率-但没有数据冗余保护-。" tabindex="-1">Q26. 在RAID技术中，哪种RAID级别提供了最高的I/O性能和磁盘空间利用率，但没有数据冗余保护（ ）。 <a class="header-anchor" href="#q26-在raid技术中-哪种raid级别提供了最高的i-o性能和磁盘空间利用率-但没有数据冗余保护-。" aria-label="Permalink to &quot;Q26. 在RAID技术中，哪种RAID级别提供了最高的I/O性能和磁盘空间利用率，但没有数据冗余保护（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> RAID0</li><li><strong>B.</strong> RAID1</li><li><strong>C.</strong> RAID5</li><li><strong>D.</strong> RAID10</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q27-raid技术的主要目的是什么-。" tabindex="-1">Q27. RAID技术的主要目的是什么（ ）。 <a class="header-anchor" href="#q27-raid技术的主要目的是什么-。" aria-label="Permalink to &quot;Q27. RAID技术的主要目的是什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 提高单个磁盘的存储容量</li><li><strong>B.</strong> 降低磁盘系统的成本</li><li><strong>C.</strong> 提升数据安全性和磁盘系统效能</li><li><strong>D.</strong> 简化磁盘系统的管理</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q28-在dma传输过程中-cpu的主要任务是-。" tabindex="-1">Q28. 在DMA传输过程中，CPU的主要任务是（）。 <a class="header-anchor" href="#q28-在dma传输过程中-cpu的主要任务是-。" aria-label="Permalink to &quot;Q28. 在DMA传输过程中，CPU的主要任务是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 全程监控数据传输</li><li><strong>B.</strong> 仅在传输开始和结束时进行处理</li><li><strong>C.</strong> 持续管理数据缓冲区</li><li><strong>D.</strong> 实时协调外设与主存的通信</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q29-某硬盘有4个记录面-每面有1000个磁道-每个磁道有200个扇区-每个扇区可存储512字节。该硬盘的格式化容量是多少-。" tabindex="-1">Q29. 某硬盘有4个记录面，每面有1000个磁道，每个磁道有200个扇区，每个扇区可存储512字节。该硬盘的格式化容量是多少（ ）。 <a class="header-anchor" href="#q29-某硬盘有4个记录面-每面有1000个磁道-每个磁道有200个扇区-每个扇区可存储512字节。该硬盘的格式化容量是多少-。" aria-label="Permalink to &quot;Q29. 某硬盘有4个记录面，每面有1000个磁道，每个磁道有200个扇区，每个扇区可存储512字节。该硬盘的格式化容量是多少（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 400MB</li><li><strong>B.</strong> 800MB</li><li><strong>C.</strong> 400GB</li><li><strong>D.</strong> 800GB</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>解析：</p><p>容量计算：</p><ul><li>记录面数：4</li><li>每面磁道数：1000</li><li>每磁道扇区数：200</li><li>每扇区字节数：512</li></ul><p>总字节数 = 4 × 1000 × 200 × 512<br> = 4 × 1000 × 102400<br> = 4 × 102,400,000<br> = 409,600,000 字节</p><p>换算为 MB（按 1 MB = 10⁶ 字节，硬盘常用标称）：<br> 409,600,000 ÷ 1,000,000 = 409.6 MB ≈ <strong>400 MB</strong>（选项中最接近）</p><p>若按二进制 1 MB = 2²⁰ = 1,048,576 字节，则约为 390.6 MB，仍接近 400 MB。<br> 选项 B、C、D 数值过大，因此 <strong>A 正确</strong>。</p></div></details><h2 id="q30-在计算机系统中-硬盘的存取时间主要由哪些部分组成-。" tabindex="-1">Q30. 在计算机系统中，硬盘的存取时间主要由哪些部分组成（ ）。 <a class="header-anchor" href="#q30-在计算机系统中-硬盘的存取时间主要由哪些部分组成-。" aria-label="Permalink to &quot;Q30. 在计算机系统中，硬盘的存取时间主要由哪些部分组成（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 寻道时间、等待时间、读/写时间</li><li><strong>B.</strong> 寻道时间、等待时间</li><li><strong>C.</strong> 寻道时间、读/写时间</li><li><strong>D.</strong> 等待时间、读/写时间</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><p>解析</p><ul><li><strong>寻道时间</strong>：磁头移动到目标磁道所需的时间。</li><li><strong>等待时间</strong>（旋转延迟）：目标扇区旋转到磁头下方所需的时间。</li><li><strong>读/写时间</strong>：数据实际传输的时间。</li></ul><p>三者之和即为硬盘的存取时间。因此 A 完整准确。</p><h2 id="q31-在磁盘移臂调度算法中-以下哪种算法可能会导致-饥饿-现象-。" tabindex="-1">Q31. 在磁盘移臂调度算法中，以下哪种算法可能会导致&#39;饥饿&#39;现象（ ）。 <a class="header-anchor" href="#q31-在磁盘移臂调度算法中-以下哪种算法可能会导致-饥饿-现象-。" aria-label="Permalink to &quot;Q31. 在磁盘移臂调度算法中，以下哪种算法可能会导致&#39;饥饿&#39;现象（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 先来先服务（FCFS）</li><li><strong>B.</strong> 最短寻道时间优先（SSTF）</li><li><strong>C.</strong> 扫描算法（SCAN）</li><li><strong>D.</strong> 循环扫描（C-SCAN）算法</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q32-在移动和穿戴设备中-不属于常见外部设备的是-。" tabindex="-1">Q32. 在移动和穿戴设备中，不属于常见外部设备的是（ ）。 <a class="header-anchor" href="#q32-在移动和穿戴设备中-不属于常见外部设备的是-。" aria-label="Permalink to &quot;Q32. 在移动和穿戴设备中，不属于常见外部设备的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> GPS设备</li><li><strong>B.</strong> 加速计</li><li><strong>C.</strong> 打印机</li><li><strong>D.</strong> 陀螺仪</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q33-下列哪个不属于串行总线-。" tabindex="-1">Q33. 下列哪个不属于串行总线（ ）。 <a class="header-anchor" href="#q33-下列哪个不属于串行总线-。" aria-label="Permalink to &quot;Q33. 下列哪个不属于串行总线（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> USB</li><li><strong>B.</strong> SATA</li><li><strong>C.</strong> PCI</li><li><strong>D.</strong> RapidIO</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>正确答案是 <strong>C. PCI</strong>。</p><p>解析</p><ul><li><strong>A. USB</strong>：通用串行总线，标准串行总线。</li><li><strong>B. SATA</strong>：串行高级技术附件，串行总线。</li><li><strong>C. PCI</strong>：传统外设组件互连总线，<strong>并行总线</strong>（非串行）。PCIe（PCI Express）才是串行，但此处 PCI 指早期并行版本。</li><li><strong>D. RapidIO</strong>：高性能嵌入式串行总线。</li></ul><p><strong>方法技巧</strong>：</p><p>判断一种总线是串行还是并行，关键看数据线是否多根并行传输。串行总线只有一根（或一对差分线）逐位传输，常见如 USB、SATA、PCIe、RapidIO、I²C、SPI 等；并行总线有多根数据线同时传输多位，如传统 PCI、ISA、PATA（IDE）等。<br> 考试中若出现“PCI”未说明“PCIe”，通常指并行 PCI，故不属于串行总线。</p></div></details><h2 id="q34-关于计算机总线的分类-下列说法错误的是-。" tabindex="-1">Q34. 关于计算机总线的分类，下列说法错误的是（ ）。 <a class="header-anchor" href="#q34-关于计算机总线的分类-下列说法错误的是-。" aria-label="Permalink to &quot;Q34. 关于计算机总线的分类，下列说法错误的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 片上总线是芯片内部互连的总线</li><li><strong>B.</strong> 系统总线连接CPU、主存和I/O接口</li><li><strong>C.</strong> 外部总线只用于连接外部存储设备</li><li><strong>D.</strong> 内总线也称为片内总线</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q35-已知cache的访问命中率为0-8-cache存取时间为20ns-主存访问时间为100ns-则系统的平均访问时间为-。" tabindex="-1">Q35. 已知Cache的访问命中率为0.8，Cache存取时间为20ns，主存访问时间为100ns，则系统的平均访问时间为（ ）。 <a class="header-anchor" href="#q35-已知cache的访问命中率为0-8-cache存取时间为20ns-主存访问时间为100ns-则系统的平均访问时间为-。" aria-label="Permalink to &quot;Q35. 已知Cache的访问命中率为0.8，Cache存取时间为20ns，主存访问时间为100ns，则系统的平均访问时间为（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 36ns</li><li><strong>B.</strong> 60ns</li><li><strong>C.</strong> 80ns</li><li><strong>D.</strong> 84ns</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q36-下列关于程序局部性原理的描述-错误的是-。" tabindex="-1">Q36. 下列关于程序局部性原理的描述，错误的是（ ）。 <a class="header-anchor" href="#q36-下列关于程序局部性原理的描述-错误的是-。" aria-label="Permalink to &quot;Q36. 下列关于程序局部性原理的描述，错误的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 时间局部性指程序中的循环操作容易再次执行</li><li><strong>B.</strong> 空间局部性指程序访问的地址往往集中在一定范围</li><li><strong>C.</strong> 局部性原理只适用于循环程序</li><li><strong>D.</strong> 数组访问体现了空间局部性特征</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q37-cache存储器设计的理论依据是-。" tabindex="-1">Q37. Cache存储器设计的理论依据是（ ）。 <a class="header-anchor" href="#q37-cache存储器设计的理论依据是-。" aria-label="Permalink to &quot;Q37. Cache存储器设计的理论依据是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 程序的局部性原理</li><li><strong>B.</strong> 程序的并行性原理</li><li><strong>C.</strong> 存储器的分级原理</li><li><strong>D.</strong> 程序的顺序性原理</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p><p>解析</p><ul><li><strong>局部性原理</strong>包括时间局部性（刚访问的数据可能再次访问）和空间局部性（附近的数据可能被访问），这是 Cache 能够显著提高命中率的理论基础。</li><li><strong>B</strong> 并行性原理用于多核、流水线等，与 Cache 设计无关。</li><li><strong>C</strong> 存储分级是体系结构的事实，但 Cache 的存在依据是局部性，而非分级本身。</li><li><strong>D</strong> 顺序性原理没有此说法。</li></ul><p>因此，Cache 设计的核心理论依据是 <strong>程序的局部性原理</strong>。</p></div></details><h2 id="q38-在计算机存储层次结构中-下列哪种存储器在掉电后仍能保持数据-。" tabindex="-1">Q38. 在计算机存储层次结构中，下列哪种存储器在掉电后仍能保持数据（ ）。 <a class="header-anchor" href="#q38-在计算机存储层次结构中-下列哪种存储器在掉电后仍能保持数据-。" aria-label="Permalink to &quot;Q38. 在计算机存储层次结构中，下列哪种存储器在掉电后仍能保持数据（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> DRAM主存</li><li><strong>B.</strong> 片上缓存</li><li><strong>C.</strong> 片外缓存</li><li><strong>D.</strong> 磁盘外存</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q39-在计算机存储层次结构中-关于片上缓存的特点-正确的是-。" tabindex="-1">Q39. 在计算机存储层次结构中，关于片上缓存的特点，正确的是（ ）。 <a class="header-anchor" href="#q39-在计算机存储层次结构中-关于片上缓存的特点-正确的是-。" aria-label="Permalink to &quot;Q39. 在计算机存储层次结构中，关于片上缓存的特点，正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 容量大、速度慢、成本低</li><li><strong>B.</strong> 容量小、速度快、成本高</li><li><strong>C.</strong> 容量大、速度快、成本低</li><li><strong>D.</strong> 容量小、速度慢、成本高</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q40-risc指令系统的特点包括-。-1指令数量少-2寻址方式多-3指令格式种类少-4指令长度固定" tabindex="-1">Q40. RISC指令系统的特点包括（）。 ①指令数量少 ②寻址方式多 ③指令格式种类少 ④指令长度固定 <a class="header-anchor" href="#q40-risc指令系统的特点包括-。-1指令数量少-2寻址方式多-3指令格式种类少-4指令长度固定" aria-label="Permalink to &quot;Q40. RISC指令系统的特点包括（）。 ①指令数量少 ②寻址方式多 ③指令格式种类少 ④指令长度固定&quot;">​</a></h2><ul><li><strong>A.</strong> ①②③</li><li><strong>B.</strong> ①②④</li><li><strong>C.</strong> ①③④</li><li><strong>D.</strong> ②③④</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q41-关于计算机系统存储器层次结构-下列说法错误的是-。" tabindex="-1">Q41. 关于计算机系统存储器层次结构，下列说法错误的是（ ）。 <a class="header-anchor" href="#q41-关于计算机系统存储器层次结构-下列说法错误的是-。" aria-label="Permalink to &quot;Q41. 关于计算机系统存储器层次结构，下列说法错误的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 片上缓存直接集成在处理器核心中，速度最快</li><li><strong>B.</strong> 主存采用DRAM结构，需要不断充电维持数据</li><li><strong>C.</strong> 外存在掉电后能保持数据，容量最大</li><li><strong>D.</strong> L2Cache必须采用DRAM结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q42-下列关于处理器指令集的描述-错误的是-。" tabindex="-1">Q42. 下列关于处理器指令集的描述，错误的是（ ）。 <a class="header-anchor" href="#q42-下列关于处理器指令集的描述-错误的是-。" aria-label="Permalink to &quot;Q42. 下列关于处理器指令集的描述，错误的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 处理器指令集可分为CISC和RISC两类</li><li><strong>B.</strong> Intel的x86 CPU属于CISC架构</li><li><strong>C.</strong> ARM处理器属于RISC架构</li><li><strong>D.</strong> CISC和RISC的主要区别在于处理器核心数量</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p></div></details><h2 id="q43-关于gpu-图形处理器-的特点-下列说法正确的是-。" tabindex="-1">Q43. 关于GPU（图形处理器）的特点，下列说法正确的是（ ）。 <a class="header-anchor" href="#q43-关于gpu-图形处理器-的特点-下列说法正确的是-。" aria-label="Permalink to &quot;Q43. 关于GPU（图形处理器）的特点，下列说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 主要用于常规的串行计算处理</li><li><strong>B.</strong> 具有数百或数千个内核，适合并行计算</li><li><strong>C.</strong> 专门用于实时的数字信号处理</li><li><strong>D.</strong> 主要用于可编程逻辑门阵列设计</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q44-关于现代计算机处理器的特点-下列说法正确的是-。" tabindex="-1">Q44. 关于现代计算机处理器的特点，下列说法正确的是（ ）。 <a class="header-anchor" href="#q44-关于现代计算机处理器的特点-下列说法正确的是-。" aria-label="Permalink to &quot;Q44. 关于现代计算机处理器的特点，下列说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 控制单元和运算单元必须分开设计</li><li><strong>B.</strong> 控制单元和运算单元被集成为一体</li><li><strong>C.</strong> 处理器只包含控制单元和运算单元两部分</li><li><strong>D.</strong> 处理器不包含控制单元</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>解析</p><ul><li><strong>A</strong> ❌：现代处理器中控制单元和运算单元集成在同一芯片内，并非必须分开。</li><li><strong>B</strong> ✅：正确，CPU 将控制单元和运算单元（ALU）等集成在一起。</li><li><strong>C</strong> ❌：不完整，处理器还包含寄存器、缓存等部件。</li><li><strong>D</strong> ❌：处理器必须包含控制单元，否则无法取指译码执行。</li></ul><p>因此，B 为正确选项。</p></div></details><h2 id="q45-以下专用处理器常用于实时的数字信号处理的是-。" tabindex="-1">Q45. 以下专用处理器常用于实时的数字信号处理的是 （ ） 。 <a class="header-anchor" href="#q45-以下专用处理器常用于实时的数字信号处理的是-。" aria-label="Permalink to &quot;Q45. 以下专用处理器常用于实时的数字信号处理的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> GPU</li><li><strong>B.</strong> DSP</li><li><strong>C.</strong> FPGA</li><li><strong>D.</strong> CPU</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q46-以下关于动态内存-dram-的叙述-错误的是-。" tabindex="-1">Q46. 以下关于动态内存（DRAM）的叙述，错误的是 （ ） 。 <a class="header-anchor" href="#q46-以下关于动态内存-dram-的叙述-错误的是-。" aria-label="Permalink to &quot;Q46. 以下关于动态内存（DRAM）的叙述，错误的是 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 需要定时刷新以保持数据</li><li><strong>B.</strong> 通常用作计算机的主存储器</li><li><strong>C.</strong> 其访问速度远高于CPU寄存器但远低于SSD</li><li><strong>D.</strong> DDR SDRAM通过时钟上下沿传输数据实现加倍速率</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q47-并行总线与串行总线的主要区别在于-。" tabindex="-1">Q47. 并行总线与串行总线的主要区别在于 （ ） 。 <a class="header-anchor" href="#q47-并行总线与串行总线的主要区别在于-。" aria-label="Permalink to &quot;Q47. 并行总线与串行总线的主要区别在于 （ ） 。&quot;">​</a></h2><ul><li><strong>A.</strong> 并行总线传输速率更高</li><li><strong>B.</strong> 串行总线需要更多数据线</li><li><strong>C.</strong> 并行总线适合短距离连接</li><li><strong>D.</strong> 串行总线无法实现双向传输</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details>',150)])])}const h=t(i,[["render",r]]);export{p as __pageData,h as default};
